# Generates uTrayIconData.pas from res/tray-en.png and res/tray-ru.png
# (32x32 RGBA PNG icons of the tray).
#
#   python tools/make-trayicons.py

import os

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')


def pascal_bytes(name, data):
    rows = []
    for i in range(0, len(data), 16):
        rows.append('    ' + ', '.join('$%02X' % b for b in data[i:i + 16]))
    return '  %s: array[0..%d] of Byte = (\r\n%s);\r\n' % (
        name, len(data) - 1, ',\r\n'.join(rows))


def main():
    out = ['unit uTrayIconData;\r\n\r\n',
           '// GENERATED by tools/make-trayicons.py from res\\tray-*.png - do not edit.\r\n\r\n',
           'interface\r\n\r\n',
           'const\r\n']
    for lang in ('En', 'Ru'):
        with open(os.path.join(ROOT, 'res', 'tray-%s.png' % lang.lower()), 'rb') as f:
            out.append(pascal_bytes('TrayIcon%sPng' % lang, f.read()))
    out.append('\r\nimplementation\r\n\r\nend.\r\n')
    with open(os.path.join(ROOT, 'uTrayIconData.pas'), 'w', encoding='ascii', newline='') as f:
        f.write(''.join(out))


if __name__ == '__main__':
    main()
